/**
 * The field entity's locals.tf contribution, in ei's exact shape: one
 * `<fieldLabel>_options_by_label` for-expression per option-carrying field
 * resource (bare field label — ei does not namespace-prefix these).
 */
import { expr } from "../../engine/tf/index.js";
// Both product selection fields need label-to-id lookups: dependent static
// options can use either a Dropdown or Multi-Select as their parent.
const OPTION_LOOKUP_FIELD_RESOURCE_TYPES = new Set([
    "elementum_dropdown_field",
    "elementum_multiselect_field",
]);
/**
 * Append one app's field-level lookup locals, keyed by the emitted field
 * addresses. Skips any dropdown field whose values come from `dynamic_config`
 * (issue #406) instead of a static `options` list — that attribute is null
 * in state for such a field, and a `for opt in ...options` local over a
 * null value fails the plan outright. Read directly off `blocks`' own attrs
 * rather than a separately-threaded address set, since the emitted field
 * blocks (already produced by `toTf`) carry this directly.
 */
export function appendFieldLocals(attrs, fieldAddresses, blocks) {
    const dynamicAddresses = new Set((blocks ?? [])
        .filter((block) => block.attrs["dynamic_config"] !== undefined)
        .map((block) => `${block.type}.${block.label}`));
    for (const address of [...fieldAddresses.values()].sort()) {
        const dot = address.indexOf(".");
        const type = address.slice(0, dot);
        const label = address.slice(dot + 1);
        if (!OPTION_LOOKUP_FIELD_RESOURCE_TYPES.has(type))
            continue;
        if (dynamicAddresses.has(address))
            continue;
        attrs[`${label}_options_by_label`] = expr.forObject("opt", expr.resourceAttr(type, label, ["options"]), expr.scopedAttr("opt", ["label"]), expr.scopedAttr("opt", ["id"]));
    }
}
